  'Targets stay where you set them.': '목표는 설정한 그대로 유지됩니다.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': '모든 세트에서 목표 횟수를 채우면 무게가 올라갑니다. 반복해서 실패하면 디로드가 걸립니다.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up — double if you double the reps. One failure resets 10 %.': '일반 두 세트에 마지막 한 세트를 실패 지점까지. 그 세트에서 목표를 넘기면 무게가 오르고, 횟수를 두 배로 하면 두 배 오릅니다. 한 번 실패하면 10 % 되돌립니다.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': '같은 무게에서 반복 범위를 올려 갑니다. 모든 세트에서 상한에 도달하면 무게가 오르고 횟수는 하한으로 돌아갑니다.',
  'Hold every set for the full duration and the target goes up.': '모든 세트를 목표 시간만큼 버티면 목표가 올라갑니다.',
  'Nothing logged yet — this session sets the baseline.': '아직 기록이 없습니다 — 이번 세션이 기준이 됩니다.',
  'Held every set for the full time — target up by {0}s.': '모든 세트를 끝까지 버텼습니다 — 목표 {0}초 상승.',
  'Short {0} sessions in a row — back off to {1}s and build up again.': '{0}회 연속으로 시간이 부족했습니다 — {1}초로 낮추고 다시 쌓으세요.',
  'Last time came up short — same target again.': '지난번엔 부족했습니다 — 같은 목표로 한 번 더.',
  'Top of the rep range in every set — {0} {1} more, back to {2} reps.': '모든 세트에서 범위 상한 도달 — {0} {1} 증가, 횟수는 {2}회로.',
  'Stalled {0} sessions — deload to {1} {2}.': '{0}회 세션 정체 — {1} {2}로 디로드.',
  'Same weight — aim for {0} reps this time.': '같은 무게 — 이번엔 {0}회를 노려보세요.',
  'Last set hit {0} reps — twice the target, so take a double jump of {1} {2}.': '마지막 세트 {0}회 — 목표의 두 배라 {1} {2}만큼 두 배로 올립니다.',
  'Every rep last time — {0} {1} more.': '지난번 전 세트 완수 — {0} {1} 증가.',
  'Missed reps {0} sessions running — reset to {1} {2} and work back up.': '{0}회 연속으로 목표 횟수 미달 — {1} {2}로 되돌리고 다시 올라가세요.',
  'Missed reps — reset to {0} {1} and work back up.': '목표 횟수 미달 — {0} {1}로 되돌리고 다시 올라가세요.',
  'Missed reps last time — same weight again ({0} of {1} to go).': '지난번 목표 횟수 미달 — 같은 무게로 한 번 더 ({1}회 중 {0}회 남음).',
  'Bodyweight — every rep last time, so go for {0} this time.': '맨몸 운동 — 지난번 전 세트 완수, 이번엔 {0}회를 노려보세요.',
  'Bodyweight — same target again until every set is clean.': '맨몸 운동 — 모든 세트가 깔끔해질 때까지 같은 목표로.',

  // --- effort per set (RIR / RPE) ---
  '{0} sets bring an {1} with them — switch on Effort per set in Settings to see it.': '{0}개 세트에 {1}이(가) 함께 들어 있습니다 — 설정에서 ‘세트당 강도’를 켜면 보입니다.',
  '{0} sets bring an {1} with them.': '{0}개 세트에 {1}이(가) 함께 들어 있습니다.',
  'RIR': 'RIR',
  'RPE': 'RPE',
  'Effort per set': '세트당 강도',
  'What are RIR and RPE?': 'RIR과 RPE란?',
  'How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.': '세트가 얼마나 힘들었는지를 무게·횟수 옆에 함께 기록합니다. 같은 판단을 양쪽 끝에서 세는 두 가지 척도입니다.',
  'How it felt': '느낌',
  'Nothing left — went to failure': '더는 못 함 — 실패 지점까지',
  'One more rep in the tank': '한 개 더 남았음',
  'Two more reps': '두 개 더 남았음',
  'Three more reps': '세 개 더 남았음',
  'Easy — warm-up territory': '가벼움 — 웜업 구간',
  'RIR counts the reps you left; RPE reads the same effort off a 10-point scale — so RPE ≈ 10 − RIR. Pick the one you already think in.': 'RIR은 남긴 횟수를 세고, RPE는 같은 노력을 10점 척도로 읽습니다 — 즉 RPE ≈ 10 − RIR. 평소에 쓰던 쪽을 고르세요.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value — progression and estimated 1RM are unaffected.': '강조된 줄은 대부분의 본세트가 들어가는 구간입니다. 이미 기록한 세트는 원래 척도를 그대로 유지하며, 이 값을 읽는 곳은 없습니다 — 프로그레션과 예상 1RM은 영향을 받지 않습니다.',
  // --- effort in the stats ---
  'Effort': '강도',
  'how close to failure': '실패 지점에 얼마나 가까운지',
