  'An AI coach that can build your plan and adjust it from what you log. Off until you turn it on.': '내 계획을 만들고 기록에 맞춰 조정해 주는 AI 코치입니다. 켜기 전까지는 꺼져 있습니다.',
  'An AI coach that can design your plan and adjust it from what you actually log. It runs on this server, it never changes anything without your say-so, and it is off until you turn it on.': '내 계획을 설계하고 실제 기록에 맞춰 조정해 주는 AI 코치입니다. 이 서버에서 실행되며, 동의 없이는 아무것도 바꾸지 않고, 켜기 전까지는 꺼져 있습니다.',
  'Any pending suggestion is discarded and scheduled reviews stop. Your Coach history stays, and you can turn it back on anytime.': '대기 중인 제안은 삭제되고 예약된 리뷰는 중단됩니다. 기록은 남으며 언제든 다시 켤 수 있습니다.',
  'Anything else?': '그 밖에는요?',
