  'When you ask for a plan or a review, this instance sends the following to {0}, running on this server under the instance owner’s account.': '계획이나 리뷰를 요청하면, 이 인스턴스는 다음 정보를 이 서버에서 운영자 계정으로 실행 중인 {0}에 전송합니다.',
