  'Lock screen & background': '잠금 화면 및 백그라운드',
  'The live step notification shows your steps, a seconds-ticking clock, walking time and the countdown to midnight on the lock screen. Some phones (Xiaomi, Huawei, Samsung…) also need MAHDI-JYM allowed to run in the background in their battery settings.': '실시간 걸음 알림은 잠금 화면에 걸음 수, 초 단위 시계, 걷기 시간, 자정까지 카운트다운을 보여 줍니다. 일부 휴대폰(Xiaomi, Huawei, Samsung 등)은 배터리 설정에서 MAHDI-JYM의 백그라운드 실행도 허용해야 합니다.',
  'Keep counting in the background': '백그라운드에서 계속 세기',
  'Allowed — the phone won’t stop the counter.': '허용됨 — 휴대폰이 카운터를 멈추지 않습니다.',
  'Exempt MAHDI-JYM from battery optimisation so the phone never stops the counter.': 'MAHDI-JYM을 배터리 최적화에서 제외해 휴대폰이 카운터를 멈추지 않게 하세요.',
  'Notification settings': '알림 설정',
  'Show the step counter on the lock screen, with sound for milestones.': '잠금 화면에 걸음 수를 표시하고, 마일스톤에 소리를 냅니다.',
  'Home-screen widget': '홈 화면 위젯',
  'Long-press your home screen → Widgets → MAHDI-JYM to add the live step counter.': '홈 화면을 길게 누르고 → 위젯 → MAHDI-JYM을 선택해 실시간 걸음 수를 추가하세요.',
  'To reach your goal: {0} steps per hour until midnight': '목표 달성까지: 자정까지 시간당 {0}걸음',
  'On Android the counter runs as a background service: it keeps counting with the app closed and the phone locked, and shows your steps live in the notification and on the lock screen.': 'Android에서는 카운터가 백그라운드 서비스로 실행됩니다. 앱을 닫고 휴대폰을 잠가도 계속 세며, 알림과 잠금 화면에 걸음 수를 실시간으로 보여 줍니다.',
