  'That’s {0} less than {1} ago — real weight rarely moves that fast. Save it anyway?': '{1} 전보다 {0} 줄었습니다 — 실제 체중은 이렇게 빨리 변하는 경우가 드뭅니다. 그래도 저장할까요?',
