  'Start the demo': '데모 시작',
  'This demo runs entirely in your browser on example data — nothing is sent anywhere. Passkey sign-in and sync across your devices come with the MAHDI-JYM server, which you get by self-hosting it.': '이 데모는 예시 데이터로 브라우저 안에서만 실행되며 어디에도 전송되지 않습니다. 패스키 로그인과 기기 간 동기화는 직접 호스팅하는 MAHDI-JYM 서버에서 제공됩니다.',
