  'Horizontal pressing, the other half of the session.': '수평 프레스, 세션의 나머지 절반.',
  'A pull for every press, so the shoulders stay balanced.': '프레스마다 풀을 하나씩 — 어깨 균형을 위해.',
  'The main lower-body driver — where most of the strength comes from.': '하체의 핵심 운동 — 대부분의 근력이 여기서 나옵니다.',
  'The two big lower-body and pressing patterns first, while you are fresh.': '체력이 남아 있을 때 하체와 프레스, 두 가지 큰 패턴을 먼저.',
  'The same patterns, different variations — enough overlap to progress, enough difference to stay fresh.': '같은 패턴, 다른 변형 — 성장할 만큼 겹치고, 지루하지 않을 만큼 다릅니다.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': '입력한 장비로 구성한 주 3회, 2일 로테이션입니다. 복합 운동을 먼저, 프레스마다 풀 하나, 그리고 2주 동안 빠지는 부위가 없도록 날마다 충분히 겹치게 했습니다.',
  'Based on the training already in this demo profile.': '이 데모 프로필에 있는 운동 기록을 바탕으로 했습니다.',
  'No training history yet — starting conservatively.': '운동 기록이 없어 보수적으로 시작합니다.',
  'The Coach is already thinking about your training.': '코치가 이미 운동을 분석하고 있습니다.',
  'Revised as you asked. Everything you did not question is exactly as it was.': '요청대로 수정했습니다. 문의하지 않은 부분은 그대로입니다.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': '이 운동의 탑 세트가 3회 연속 RPE 9.5 이상이었는데 무게는 그대로입니다. 4주간 동작을 바꾸면 같은 운동을 고집하는 것보다 보통 정체를 더 빨리 깹니다.',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': '세션이 15분 정도 길어지고 있습니다. 세트를 하나 줄여도 손해가 가장 적은 보조 운동입니다.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': '3주 연속 이 세션을 토요일로 옮기셨습니다. 매번 바꾸는 것보다 계획에 반영하는 편이 낫습니다.',
  'Three things worth changing, and one worth knowing about. Everything else is working — the squat and the pulls are both progressing on schedule.': '바꿀 만한 것 세 가지와 알아 둘 것 하나. 나머지는 잘 되고 있습니다 — 스쿼트와 풀 동작 모두 예정대로 늘고 있어요.',
  'Body weight has been flat for four weeks while the goal is to gain. That is a kitchen problem rather than a training one — the plan is not what is holding it back.': '증량이 목표인데 4주째 체중이 그대로입니다. 운동보다는 식단 문제입니다 — 계획이 발목을 잡는 게 아닙니다.',
  // 2.2
  'Physical activity': '신체 활동',
  'Counts every step you take.': '걸음 하나하나를 셉니다.',
  'Live step counter on the lock screen, alerts every 1,000 steps.': '잠금 화면에 실시간 걸음 수 표시, 1,000걸음마다 알림.',
  'Run in the background': '백그라운드에서 실행',
  'Keeps counting with the app closed and the screen off — no stopping.': '앱을 닫고 화면이 꺼져도 멈추지 않고 계속 셉니다.',
  'Start after restart': '재시작 후 자동 시작',
  'Switches itself back on when the phone is turned off and on again.': '휴대폰을 껐다 켜면 스스로 다시 켜집니다.',
  'Step counter on': '만보기 켜짐',
  'Starts counting right away.': '바로 세기 시작합니다.',
  'Counts while this page is open.': '이 페이지가 열려 있는 동안 셉니다.',
  'Welcome to MAHDI-JYM': 'MAHDI-JYM에 오신 것을 환영합니다',
  'To count your steps all day — in the background, with the screen locked and after a restart — MAHDI-JYM needs a few permissions.': '하루 종일 — 백그라운드에서, 화면이 잠겨 있을 때도, 재시작 후에도 — 걸음을 세려면 MAHDI-JYM에 몇 가지 권한이 필요합니다.',
  'To count your steps and notify you, MAHDI-JYM needs a few permissions.': '걸음을 세고 알림을 보내려면 MAHDI-JYM에 몇 가지 권한이 필요합니다.',
  'By tapping Agree you use MAHDI-JYM at your own responsibility. It is not a medical device: steps, distance, calories and speed are estimates. Check with a doctor before starting a training program. Your data stays on your device.': '동의를 누르면 본인 책임 하에 MAHDI-JYM을 사용하게 됩니다. 이 앱은 의료 기기가 아니며 걸음 수, 거리, 칼로리, 속도는 추정치입니다. 운동 프로그램을 시작하기 전에 의사와 상담하세요. 데이터는 기기에만 저장됩니다.',
  'Agree & allow': '동의하고 허용',
  'Setting up…': '설정 중…',
  'Answer “Allow” on each screen that appears.': '나타나는 각 화면에서 “허용”을 선택하세요.',
  'One more step': '한 단계 더',
  '{0} phones also stop apps in the background unless you allow them. Turn on Autostart (or “No restrictions”) for MAHDI-JYM.': '{0} 휴대폰은 허용하지 않으면 백그라운드 앱도 중지합니다. MAHDI-JYM의 자동 실행(또는 “제한 없음”)을 켜세요.',
  'Open settings': '설정 열기',
  'All set': '모두 준비됨',
  'MAHDI-JYM now counts your steps in the background, also with the screen off and after a restart. You can change this any time under Walking.': '이제 MAHDI-JYM이 화면이 꺼져 있을 때와 재시작 후에도 백그라운드에서 걸음을 셉니다. 언제든지 걷기에서 변경할 수 있습니다.',
  'Browsers can only count while the page is open. For counting in the background, with the screen off and after a restart, install the Android app.': '브라우저는 페이지가 열려 있는 동안에만 셀 수 있습니다. 백그라운드, 화면 꺼짐, 재시작 후에도 세려면 Android 앱을 설치하세요.',
  'Download the Android app': 'Android 앱 다운로드',
  'Clear': '지우기',
