  'Next month': '다음 달',
  'Previous week': '이전 주',
  'Next week': '다음 주',
  'Passkeys don’t work inside an embedded preview. Open MAHDI-JYM in its own tab.': '패스키는 삽입된 미리보기 안에서 작동하지 않습니다. MAHDI-JYM을 별도의 탭에서 여세요.',
  'The passkey was cancelled or timed out. Try again.': '패스키가 취소되었거나 시간이 초과되었습니다. 다시 시도하세요.',
  'This device already has a passkey for MAHDI-JYM — sign in with it instead.': '이 기기에는 이미 MAHDI-JYM 패스키가 있습니다 — 그 패스키로 로그인하세요.',
  'Passkeys need the app to be opened at its own https address.': '패스키를 사용하려면 앱을 자체 https 주소에서 열어야 합니다.',
  'This page is shown inside a preview frame, where browsers block passkeys. Open it in its own tab to sign in or create a profile — or continue without an account.': '이 페이지는 브라우저가 패스키를 차단하는 미리보기 프레임 안에 표시되고 있습니다. 로그인하거나 프로필을 만들려면 별도의 탭에서 여세요 — 또는 계정 없이 계속하세요.',
  'Open in a new tab': '새 탭에서 열기',
