  'In the browser, reminders appear while MAHDI-JYM is open. Install the Android app for reminders with the app closed.': '브라우저에서는 MAHDI-JYM이 열려 있는 동안 알림이 표시됩니다. 앱이 닫혀 있을 때도 받으려면 Android 앱을 설치하세요.',
