  'When a goal is reached with the app closed, Android shows the celebration over the lock screen. To see it on top of other apps too, allow “Display over other apps”.': '앱이 닫힌 상태에서 목표를 달성하면 Android가 잠금 화면 위에 축하 화면을 보여 줍니다. 다른 앱 위에도 보려면 ‘다른 앱 위에 표시’를 허용하세요.',
  'Full screen, with confetti and a fanfare, at every 1,000 steps and at your goal.': '1,000걸음마다, 그리고 목표 달성 시 색종이와 팡파르가 있는 전체 화면.',
