  // 2.6 — Google account, automatic water goal, water panel, workout reminders
  'Google sign-in isn’t set up for this version of the app yet. Your data stays on this phone for now.': '이 앱 버전에는 아직 Google 로그인이 설정되지 않았습니다. 지금은 데이터가 이 휴대폰에 보관됩니다.',
  'No connection to Google. Check the internet and try again.': 'Google에 연결할 수 없습니다. 인터넷을 확인하고 다시 시도하세요.',
  'Google Drive access wasn’t allowed, so nothing can be saved to the account.': 'Google Drive 접근이 허용되지 않아 계정에 저장할 수 없습니다.',
  'Google Play services aren’t available on this phone.': '이 휴대폰에서는 Google Play 서비스를 사용할 수 없습니다.',
  'Google sign-in didn’t work. Try again, or keep your data on this phone.': 'Google 로그인에 실패했습니다. 다시 시도하거나 데이터를 이 휴대폰에 보관하세요.',
  'Keep your progress safe': '진행 기록을 안전하게',
  'Sign in with a Google account that’s already on this phone — no password — and every workout, step, glass of water and setting is saved to it. Or keep everything on this phone.': '이 휴대폰에 이미 있는 Google 계정으로 로그인하세요 — 비밀번호 없이 — 모든 운동, 걸음, 물 한 잔, 설정이 계정에 저장됩니다. 또는 모두 이 휴대폰에 보관하세요.',
  'Continue with Google': 'Google로 계속하기',
