  'Saved in a private app folder in your Google Drive that only MAHDI-JYM can see. Sign out anytime in Settings.': 'MAHDI-JYM만 볼 수 있는 Google Drive의 비공개 앱 폴더에 저장됩니다. 언제든 설정에서 로그아웃할 수 있습니다.',
