  'Put routines on days in Plan — each one gets its reminder.': '계획에서 요일에 루틴을 배치하세요 — 각각 알림이 설정됩니다.',
  'For every day — or set a time per day below': '매일 — 또는 아래에서 요일별 시간 설정',
  'Reminds you on days that have a routine planned and not yet trained — with the exercises, about how long it takes and your step goal in the same notification.': '루틴이 계획되어 있고 아직 운동하지 않은 날 알려 줍니다 — 운동 목록, 예상 소요 시간, 걸음 목표를 한 알림에.',
  '{0} ml per 1,000 steps after the first {1}, and {2} ml per minute of training. Updates through the day — also in the notification.': '처음 {1}걸음 이후 1,000걸음마다 {0}ml, 운동 1분마다 {2}ml. 하루 동안 업데이트됩니다 — 알림에서도.',
  'Automatic goal': '자동 목표',
