  'Tap a glass, cup, can or bottle in the notification to add it, Undo to take the last one back, Edit to open this screen — all with the app closed.': '알림에서 유리잔, 컵, 캔, 병을 눌러 추가하고, 실행 취소로 마지막 것을 되돌리고, 편집으로 이 화면을 엽니다 — 앱을 닫은 상태에서도.',
