  'In one bar with the step counter — tidy and always at hand': '걸음 수와 함께 하나의 알림에 — 깔끔하고 언제나 가까이',
  // 2.8 — Google account without setup (Android Backup)
  'Welcome back — your data was restored from your Google account': '다시 오신 것을 환영합니다 — Google 계정에서 데이터를 복원했습니다',
  'Google Drive isn’t set up for this version of the app yet — your data is still saved to your Google account through Android Backup.': '이 앱 버전에는 아직 Google Drive가 설정되지 않았습니다. 그래도 데이터는 Android 백업을 통해 Google 계정에 저장됩니다.',
  'Saved privately to your Google account — only MAHDI-JYM can read it. Sign out anytime in Settings.': 'Google 계정에 비공개로 저장됩니다 — MAHDI-JYM만 읽을 수 있습니다. 설정에서 언제든 로그아웃할 수 있습니다.',
  'Everything is saved to your Google account automatically through Android Backup, and comes back when you install MAHDI-JYM again.': '모든 데이터가 Android 백업을 통해 Google 계정에 자동 저장되며, MAHDI-JYM을 다시 설치하면 돌아옵니다.',
  'Now saved to Google Drive': '이제 Google Drive에 저장됩니다',
  'Your data stays on this phone. Changes are no longer saved to your Google account.': '데이터는 이 휴대폰에 남습니다. 변경 사항은 더 이상 Google 계정에 저장되지 않습니다.',
  'Sign in with a Google account that’s already on this phone — no password. Everything is then saved to that account automatically.': '이 휴대폰에 이미 있는 Google 계정으로 로그인하세요 — 비밀번호 없이. 이후 모든 데이터가 그 계정에 자동 저장됩니다.',
  'Workouts, plan, steps, water, body weight and settings are saved through Android Backup to your Google account. Android uploads it in the background, usually within a few hours, and puts it back when you install MAHDI-JYM again or on a new phone. Progress photos stay on this phone.': '운동, 계획, 걸음, 물, 체중, 설정이 Android 백업을 통해 Google 계정에 저장됩니다. Android가 백그라운드에서 보통 몇 시간 안에 업로드하고, MAHDI-JYM을 다시 설치하거나 새 휴대폰에 설치하면 복원합니다. 진행 사진은 이 휴대폰에 남습니다.',
  'Google Drive': 'Google Drive',
