  "Once a day, when something changed, a full copy is kept on this phone and in Google Drive. The newest ones are kept; older ones are removed.": "하루에 한 번, 변경 사항이 있으면 이 휴대폰과 Google Drive에 전체 사본을 보관합니다. 최신 사본은 남기고 오래된 사본은 삭제합니다.",
  "Once a day, when something changed, a full copy is kept on this phone. The newest ones are kept; older ones are removed.": "하루에 한 번, 변경 사항이 있으면 이 휴대폰에 전체 사본을 보관합니다. 최신 사본은 남기고 오래된 사본은 삭제합니다.",
