  "No versions in Drive yet.": "아직 Drive에 버전이 없습니다.",
  "A version is a full copy: workouts, plan, routines, steps, water, body weight, health log and settings. Progress photos stay where they are. For a copy you can keep anywhere, use Export in Settings.": "버전은 운동, 계획, 루틴, 걸음, 물, 체중, 건강 기록, 설정을 모두 담은 전체 사본입니다. 진행 사진은 그대로 남습니다. 어디에나 보관할 사본이 필요하면 설정의 내보내기를 사용하세요.",
  "Open console.cloud.google.com with your Google account and create a project (any name).": "Google 계정으로 console.cloud.google.com을 열고 프로젝트를 만드세요(이름 무관).",
  "APIs & Services → Library → search “Google Drive API” → Enable.": "APIs & Services → Library → “Google Drive API” 검색 → Enable.",
  "OAuth consent screen → External → fill in the app name and your email → add the scope …/auth/drive.appdata → add your own account as a test user.": "OAuth consent screen → External → 앱 이름과 이메일 입력 → 범위 …/auth/drive.appdata 추가 → 내 계정을 테스트 사용자로 추가.",
  "Credentials → Create credentials → OAuth client ID → Android → paste the package name and SHA-1 below.": "Credentials → Create credentials → OAuth client ID → Android → 아래 패키지 이름과 SHA-1 붙여넣기.",
  "Wait about 5 minutes, then come back here and tap Try again. Nothing changes in the app itself.": "5분 정도 기다린 후 여기로 돌아와 다시 시도를 누르세요. 앱 자체는 바뀌지 않습니다.",
  "Switch on Google Drive": "Google Drive 켜기",
