  "The Google Drive API is switched off in the Cloud project": "Cloud 프로젝트에서 Google Drive API가 꺼져 있습니다",
  "In Google Cloud: APIs & Services → Library → Google Drive API → Enable. Then test again in a few minutes.": "Google Cloud에서: API 및 서비스 → 라이브러리 → Google Drive API → 사용. 몇 분 뒤 다시 테스트하세요.",
  "Google doesn’t know this app yet": "Google이 아직 이 앱을 모릅니다",
  "Create an Android OAuth client in Google Cloud with exactly the package name and SHA-1 shown here. Wait about 5 minutes, then test again.": "Google Cloud에서 여기 표시된 패키지 이름과 SHA-1 그대로 Android OAuth 클라이언트를 만드세요. 약 5분 기다린 뒤 다시 테스트하세요.",
  "Access to Google Drive wasn’t allowed": "Google Drive 접근이 허용되지 않았습니다",
  "Tap Test Google Drive and choose Allow. While the app is in testing, your account must be listed as a test user on the OAuth consent screen.": "‘Google Drive 테스트’를 누르고 허용을 선택하세요. 앱이 테스트 중인 동안에는 OAuth 동의 화면에 계정이 테스트 사용자로 등록되어 있어야 합니다.",
  "Google refused access for this account": "Google이 이 계정의 접근을 거부했습니다",
  "On the OAuth consent screen: user type External, your account added as a test user, and the scope …/auth/drive.appdata added. Then test again.": "OAuth 동의 화면에서: 사용자 유형 외부, 계정을 테스트 사용자로 추가, 범위 …/auth/drive.appdata 추가. 그런 다음 다시 테스트하세요.",
