  "School Sunday to Thursday, 7:30 to 12:40, then lunch, rest, homework, work, drinks and dinner — and a calmer weekend.": "일~목 등교 7:30~12:40, 그 뒤 점심, 휴식, 숙제, 일, 음료, 저녁 — 그리고 여유로운 주말.",
  "Each reminder shows the time, your notes and the food and drinks you chose with their calories — with Done ✓ and In 10 min.": "각 알림에 시간, 메모, 고른 음식·음료와 칼로리가 표시되고 '완료 ✓'와 '10분 후'가 있어요.",
  "Colas, lemon-lime, fruit sodas, malt and energy drinks and homemade mojitos — in cans, bottles and glasses of every size, with sugar in teaspoons.": "콜라, 레몬라임, 과일 탄산, 맥아·에너지 음료, 홈메이드 모히토 — 모든 크기의 캔·병·잔으로, 설탕은 티스푼으로.",
  "Pistachios, almonds, walnuts, cashews, the seeds you crack and kerzat — raw, roasted or salted, by the handful, with what each is good for.": "피스타치오, 아몬드, 호두, 캐슈, 까먹는 씨앗과 견과 믹스 — 생·볶음·소금, 한 줌 단위로, 각각의 효능과 함께.",
  "All notifications in one place": "모든 알림을 한곳에",
  "Which reminders are on, what still rings today, and the phone’s notification settings grouped by kind.": "켜진 알림, 오늘 남은 알림, 종류별로 묶인 휴대폰 알림 설정까지.",
