  "Soda & sparkling water": "소다수·탄산수",
  "Soda and sparkling water have no calories. Tonic water and ginger ale are sweetened.": "소다수와 탄산수는 칼로리가 없어요. 토닉워터와 진저에일은 달게 만들어요.",
  "Malt drinks 0.0%": "몰트 음료 0.0%",
  "Malt drinks have no alcohol. The flavoured ones are as sweet as soft drinks; the classic is lighter.": "몰트 음료에는 알코올이 없어요. 향이 들어간 건 탄산음료만큼 달고, 클래식은 더 가벼워요.",
  "Energy drinks": "에너지 음료",
  "Lots of caffeine and sugar. Not for children, pregnancy or anyone sensitive to caffeine — one can a day at most.": "카페인과 당이 많아요. 어린이, 임산부, 카페인에 민감한 사람은 피하세요 — 하루 최대 한 캔.",
  "Homemade sodas": "홈메이드 탄산음료",
  "Made at home with soda water, fresh lemon and mint — you decide how sweet. Values assume a little sugar.": "탄산수, 생레몬, 민트로 집에서 만들어요 — 단맛은 직접 정해요. 값은 설탕을 조금 넣은 기준이에요.",
  "High in caffeine — not for children, pregnancy or anyone sensitive to caffeine. Never mix it with alcohol, and not during hard exercise in the heat.": "카페인이 많아요 — 어린이, 임산부, 카페인에 민감한 사람은 피하세요. 술과 절대 섞지 말고, 더운 날 격한 운동 중에도 마시지 마세요.",
